function uid(prefix: string) { return `${prefix}-${crypto.randomUUID()}`; }
function inputNumber(value: FormDataEntryValue | null) { return Number(String(value ?? "0").replace(",", ".")) || 0; }
function formatDate(value: string) { return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(`${value}T12:00:00`)); }
function operationIdFromPath() { return window.location.pathname.match(/^\/operacoes\/([^/]+)$/)?.[1] ?? null; }
function cnpjRaw(value: string) { return value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 14); }
function cepRaw(value: string) { return value.replace(/\D/g, "").slice(0, 8); }
function formatCep(value: string) { const raw = cepRaw(value); return raw.length > 5 ? `${raw.slice(0, 5)}-${raw.slice(5)}` : raw; }
function formatCnpj(value: string) { const raw = cnpjRaw(value); return [raw.slice(0, 2), raw.slice(2, 5), raw.slice(5, 8), raw.slice(8, 12), raw.slice(12, 14)].filter(Boolean).map((part, index) => index === 0 ? part : index === 3 ? `/${part}` : index === 4 ? `-${part}` : `.${part}`).join(""); }
function cnpjDigit(value: string) { const weights = value.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]; const remainder = [...value].reduce((sum, character, index) => sum + (character.charCodeAt(0) - 48) * weights[index], 0) % 11; return remainder < 2 ? 0 : 11 - remainder; }
function isValidCnpj(value: string) { const raw = cnpjRaw(value); if (raw.length !== 14 || (/^\d+$/.test(raw) && /^([0-9])\1+$/.test(raw))) return false; const base = raw.slice(0, 12); const first = cnpjDigit(base); return Number(raw[12]) === first && Number(raw[13]) === cnpjDigit(`${base}${first}`); }
function viewFromPath(): View { const path = window.location.pathname; if (path.startsWith("/operacoes")) return "imports"; if (path === "/clientes") return "customers"; if (path === "/portos") return "ports"; if (path === "/relatorios") return "reports"; if (path === "/pendencias") return "pending"; return "dashboard"; }
function viewUrl(view: View) { return ({ dashboard: "/", imports: "/operacoes", customers: "/clientes", ports: "/portos", reports: "/relatorios", pending: "/pendencias" } as const)[view]; }
type OperationsFilters = { query: string; status: ImportStatus | "all"; channel: CustomsSignal | "all"; sort: "oldest" | "newest" | "updated"; page: number };
function operationsFiltersFromUrl(): OperationsFilters { const params = new URLSearchParams(window.location.search); const status = params.get("status"); const channel = params.get("channel"); const sort = params.get("sort"); return { query: params.get("search") ?? "", status: status && status in importStatusMeta ? status as ImportStatus : "all", channel: channel && channel in customsChannelMeta ? channel as CustomsSignal : "all", sort: sort === "newest" || sort === "updated" ? sort : "oldest", page: Math.max(1, Number(params.get("page")) || 1) }; }
function operationsUrl(filters: OperationsFilters) { const params = new URLSearchParams(); if (filters.query) params.set("search", filters.query); if (filters.status !== "all") params.set("status", filters.status); if (filters.channel !== "all") params.set("channel", filters.channel); if (filters.sort !== "oldest") params.set("sort", filters.sort); if (filters.page > 1) params.set("page", String(filters.page)); const query = params.toString(); return `/operacoes${query ? `?${query}` : ""}`; }
function MarketPulse({ context, error }: { context: MarketContext | null; error: string }) { if (error) return <div className="market-pulse market-pulse--error" role="status">Dados operacionais indisponíveis</div>; if (!context) return <div className="market-pulse" aria-live="polite">Atualizando dados operacionais…</div>; const quoteTime = new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short" }).format(new Date(context.dollar.quotedAt)); return <section className="market-pulse" aria-label="Contexto operacional atual"><div className="market-quote"><Banknote size={16} aria-hidden="true" /><span><b>USD PTAX</b><strong>{money.format(context.dollar.sell)}</strong><small>venda · {quoteTime}</small></span></div>{context.news[0] && <a className="market-news" href={context.news[0].url} target="_blank" rel="noreferrer"><Newspaper size={15} aria-hidden="true" /><span><b>SISCOMEX</b>{context.news[0].title}</span></a>}</section>; }

export function App() { const [session, setSession] = useState<{ token: string; user: SessionUser } | null>(() => { try { return JSON.parse(sessionStorage.getItem("exporta-brasil-session") || "null") as { token: string; user: SessionUser } | null; } catch { return null; } }); const setAuthenticated = (next: { token: string; user: SessionUser } | null) => { if (next) sessionStorage.setItem("exporta-brasil-session", JSON.stringify(next)); else sessionStorage.removeItem("exporta-brasil-session"); setSession(next); }; if (!session) return <LoginScreen onAuthenticated={setAuthenticated} />; if (session.user.mustChangePassword) return <InitialPasswordScreen session={session} onAuthenticated={setAuthenticated} />; return <BackofficeApp session={session} onLogout={() => setAuthenticated(null)} />; }

function AccessLayout({ children }: { children: ReactNode }) { return <main className="login-page"><img src="/port-night-login.png" alt="Operação portuária à noite" style={{ position: "fixed", inset: 0, width: "65.25vw", height: "100vh", display: "block", maxWidth: "none", objectFit: "cover", objectPosition: "right center", transform: "scaleX(-1)", zIndex: 10 }} /><section className="login-scene" aria-hidden="true" /><section className="login-panel">{children}</section></main>; }
function LoginScreen({ onAuthenticated }: { onAuthenticated: (session: { token: string; user: SessionUser }) => void }) { const [error, setError] = useState(""); const [loading, setLoading] = useState(false); const login = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setLoading(true); setError(""); const form = new FormData(event.currentTarget); try { const response = await fetch(`${apiUrl}/api/auth/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: form.get("email"), password: form.get("password") }) }); const payload = await response.json() as { token?: string; user?: SessionUser; message?: string }; if (!response.ok || !payload.token || !payload.user) throw new Error(payload.message || "Não foi possível iniciar a sessão."); onAuthenticated({ token: payload.token, user: payload.user }); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível iniciar a sessão."); } finally { setLoading(false); } }; return <AccessLayout><section className="login-card"><div className="login-brand"><span className="brand-mark" style={{ backgroundImage: `url(${brandMark})` }} role="img" aria-label="Exporta Brasil" /><span><strong>Exporta</strong><small>Brasil</small></span></div><p className="eyebrow">ACESSO OPERACIONAL</p><h1>Boas-vindas.</h1><p>Entre para acompanhar suas operações, custos e decisões portuárias.</p><form onSubmit={login}><label><span>E-mail</span><span className="login-input"><Mail size={18} /><input name="email" type="email" required autoComplete="email" placeholder="voce@empresa.com.br" /></span></label><label><span>Senha</span><span className="login-input"><LockKeyhole size={18} /><input name="password" type="password" required autoComplete="current-password" placeholder="Sua senha" /></span></label>{error && <p className="login-error" role="alert">{error}</p>}<button className="button button--primary login-submit" disabled={loading}>{loading ? "Entrando..." : "Entrar no sistema"}</button></form><small className="login-help">Use as credenciais recebidas do administrador.</small></section></AccessLayout>; }

function InitialPasswordScreen({ session, onAuthenticated }: { session: { token: string; user: SessionUser }; onAuthenticated: (next: { token: string; user: SessionUser }) => void }) { const [error, setError] = useState(""); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const password = String(form.get("password")); if (password !== form.get("confirmation")) return setError("As senhas não coincidem."); const response = await fetch(`${apiUrl}/api/auth/change-password`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ password }) }); const payload = await response.json() as { user?: SessionUser; message?: string }; if (!response.ok || !payload.user) return setError(payload.message || "Não foi possível atualizar a senha."); onAuthenticated({ token: session.token, user: payload.user }); }; return <AccessLayout><section className="login-card"><p className="eyebrow">PRIMEIRO ACESSO</p><h1>Defina sua senha.</h1><p>Escolha uma senha pessoal para concluir a ativação da sua conta.</p><form onSubmit={submit}><label><span>Nova senha</span><span className="login-input"><LockKeyhole size={18} /><input name="password" type="password" minLength={8} required autoComplete="new-password" /></span></label><label><span>Confirme a senha</span><span className="login-input"><LockKeyhole size={18} /><input name="confirmation" type="password" minLength={8} required autoComplete="new-password" /></span></label>{error && <p className="login-error" role="alert">{error}</p>}<button className="button button--primary login-submit">Concluir acesso</button></form></section></AccessLayout>; }

function BackofficeApp({ session, onLogout }: { session: { token: string; user: SessionUser }; onLogout: () => void }) {
  const [view, setView] = useState<View>(viewFromPath);
  const [operations, setOperations] = useState<ImportOperation[]>(() => {
    try { return (JSON.parse(localStorage.getItem(storageKey) || "") as Array<Partial<ImportOperation>>).map((operation) => ({ ...operation, customsChannel: operation.customsChannel === "gray" && ["in_transit", "customs_clearance"].includes(operation.portStatus ?? "") ? "pending" : operation.customsChannel ?? "pending" } as ImportOperation)); } catch { return initialOperations; }
  });
  const [customers, setCustomers] = useState<Customer[]>(() => {
    try { return JSON.parse(localStorage.getItem(customersStorageKey) || "") as Customer[]; } catch { return initialCustomers; }
  });
  const [selectedId, setSelectedId] = useState("imp-001");
  const [detailId, setDetailId] = useState<string | null>(operationIdFromPath);
  const [operationsUrlState, setOperationsUrlState] = useState(() => window.location.search);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showNewImport, setShowNewImport] = useState(false);
  const [showNewItem, setShowNewItem] = useState(false);
  const [showTimelineEntry, setShowTimelineEntry] = useState(false);
  const [showOperationTask, setShowOperationTask] = useState(false);
  const [showOperationDocument, setShowOperationDocument] = useState(false);
  const [showNewCustomer, setShowNewCustomer] = useState(false);
  const [showUserManager, setShowUserManager] = useState(false);
  const [showCustomerPicker, setShowCustomerPicker] = useState(false);
  const [showImportCustomerForm, setShowImportCustomerForm] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [importCustomerId, setImportCustomerId] = useState("");
  const [portFacilities, setPortFacilities] = useState<PortFacility[]>([]);
  const [portCatalogState, setPortCatalogState] = useState<"idle" | "loading" | "ready" | "error">("idle");
  const [portCatalogError, setPortCatalogError] = useState("");
  const [marketContext, setMarketContext] = useState<MarketContext | null>(null);
  const [marketContextError, setMarketContextError] = useState("");

  useEffect(() => { localStorage.setItem(storageKey, JSON.stringify(operations)); }, [operations]);
  useEffect(() => { localStorage.setItem(customersStorageKey, JSON.stringify(customers)); }, [customers]);
  useEffect(() => { const syncRoute = () => { setView(viewFromPath()); setDetailId(operationIdFromPath()); setOperationsUrlState(window.location.search); }; window.addEventListener("popstate", syncRoute); return () => window.removeEventListener("popstate", syncRoute); }, []);
  useEffect(() => {
    let active = true;
    const load = () => fetch(`${apiUrl}/api/market-context`).then(async (response) => { if (!response.ok) throw new Error((await response.json() as { message?: string }).message); return response.json() as Promise<MarketContext>; }).then((data) => { if (active) { setMarketContext(data); setMarketContextError(""); } }).catch((error: unknown) => { if (active) setMarketContextError(error instanceof Error ? error.message : "Não foi possível atualizar os dados operacionais."); });
    load(); const timer = window.setInterval(load, 15 * 60 * 1000); return () => { active = false; window.clearInterval(timer); };
  }, []);
  const loadPortCatalog = () => {
    setPortCatalogState("loading"); setPortCatalogError("");
    fetch(`${apiUrl}/api/port-facilities`).then(async (response) => {
      if (!response.ok) throw new Error((await response.json() as { message?: string }).message ?? "Não foi possível carregar o catálogo.");
      return response.json() as Promise<{ data: PortFacility[] }>;
    }).then((payload) => { setPortFacilities(payload.data); setPortCatalogState("ready"); }).catch((error: unknown) => {
      setPortCatalogError(error instanceof Error ? error.message : "Não foi possível carregar o catálogo."); setPortCatalogState("error");
    });
  };
  useEffect(() => { if (view === "ports" && portCatalogState === "idle") loadPortCatalog(); }, [view, portCatalogState]);
  useEffect(() => { if (showNewImport && portCatalogState === "idle") loadPortCatalog(); }, [showNewImport, portCatalogState]);
  const selected = operations.find((operation) => operation.id === (detailId ?? selectedId)) ?? operations.find((operation) => operation.id === selectedId) ?? operations[0];
  const totalInProgress = operations.filter((item) => !["completed", "cleared"].includes(item.status)).length;
  const totalValue = useMemo(() => operations.reduce((sum, operation) => sum + calculateImport(operation).totalCost, 0), [operations]);
  const lookupCompany = async (taxId: string) => {
    const response = await fetch(`${apiUrl}/api/companies/${encodeURIComponent(cnpjRaw(taxId))}`);
    const payload = await response.json() as CompanyLookup | { message?: string };
    if (!response.ok || !("legalName" in payload)) throw new Error("message" in payload ? payload.message || "Não foi possível consultar o CNPJ." : "Não foi possível consultar o CNPJ.");
    return payload;
  };
  const lookupAddress = async (postalCode: string) => {
    const response = await fetch(`${apiUrl}/api/addresses/${encodeURIComponent(cepRaw(postalCode))}`);
    const payload = await response.json() as AddressLookup | { message?: string };
    if (!response.ok || !("street" in payload)) throw new Error("message" in payload ? payload.message || "Não foi possível consultar o CEP." : "Não foi possível consultar o CEP.");
    return payload;
  };

  const updateOperation = (id: string, changes: Partial<ImportOperation>) => {
    setOperations((current) => current.map((operation) => operation.id === id ? { ...operation, ...changes, updatedAt: new Date().toISOString() } : operation));
  };

  const createOperation = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const customerId = String(form.get("customerId"));
    const customer = customers.find((item) => item.id === customerId);
    if (!customer) return;
    const operation: ImportOperation = {
      id: uid("imp"), reference: String(form.get("reference") || `EB-${new Date().getFullYear()}-${String(operations.length + 1).padStart(3, "0")}`),
      customerId, customer: customer.tradeName || customer.legalName, supplier: String(form.get("supplier")), port: String(form.get("port")),
      container: String(form.get("container")), eta: String(form.get("eta")), status: "draft", portStatus: "awaiting_departure", customsChannel: "pending",
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), exchangeRate: 5.4, freightBrl: 0, insuranceBrl: 0, portExpensesBrl: 0, items: []
    };
    setOperations((current) => [operation, ...current]); setSelectedId(operation.id); setImportCustomerId(""); setShowNewImport(false); openOperations();
  };

  const saveCustomer = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const details = { legalName: String(form.get("legalName")), tradeName: String(form.get("tradeName")) || String(form.get("legalName")), taxId: formatCnpj(String(form.get("taxId"))), contactName: String(form.get("contactName")), email: String(form.get("email")), phone: String(form.get("phone")), postalCode: String(form.get("postalCode")), street: String(form.get("street")), number: String(form.get("number")), complement: String(form.get("complement")), district: String(form.get("district")), city: String(form.get("city")), state: String(form.get("state")).toUpperCase(), registrationStatus: String(form.get("registrationStatus")) };
    if (editingCustomer) {
      setCustomers((current) => current.map((customer) => customer.id === editingCustomer.id ? { ...customer, ...details } : customer));
    } else {
      const customer: Customer = { id: uid("customer"), ...details, status: "active", createdAt: new Date().toISOString() };
      setCustomers((current) => [customer, ...current]); setImportCustomerId(customer.id);
    }
    setEditingCustomer(null); setShowNewCustomer(false);
  };

  const saveImportCustomer = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const legalName = String(form.get("legalName"));
    const customer: Customer = { id: uid("customer"), legalName, tradeName: String(form.get("tradeName")) || legalName, taxId: formatCnpj(String(form.get("taxId"))), contactName: String(form.get("contactName")), email: String(form.get("email")), phone: String(form.get("phone")), postalCode: String(form.get("postalCode")), street: String(form.get("street")), number: String(form.get("number")), complement: String(form.get("complement")), district: String(form.get("district")), city: String(form.get("city")), state: String(form.get("state")).toUpperCase(), registrationStatus: String(form.get("registrationStatus")), status: "active", createdAt: new Date().toISOString() };
    setCustomers((current) => [customer, ...current]); setImportCustomerId(customer.id); setShowImportCustomerForm(false); setShowCustomerPicker(false);
  };

  const addItem = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const item: ImportItem = {
      id: uid("item"), name: String(form.get("name")), ncm: String(form.get("ncm")), quantity: inputNumber(form.get("quantity")),
      unitPriceUsd: inputNumber(form.get("unitPriceUsd")), grossWeightKg: inputNumber(form.get("grossWeightKg")),
      iiRate: inputNumber(form.get("iiRate")), ipiRate: inputNumber(form.get("ipiRate"))
    };
    updateOperation(selected.id, { items: [...selected.items, item] }); setShowNewItem(false);
  };
  const addTimelineEntry = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const entry: OperationTimelineEntry = { id: uid("timeline"), title: String(form.get("title")), description: String(form.get("description")) || undefined, occurredAt: String(form.get("occurredAt")) || new Date().toISOString(), type: String(form.get("type")) as OperationTimelineEntry["type"] };
    updateOperation(selected.id, { timeline: [...operationTimeline(selected), entry] }); setShowTimelineEntry(false);
  };
  const addOperationTask = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const task: OperationTask = { id: uid("task"), title: String(form.get("title")), assignee: String(form.get("assignee")) || undefined, dueDate: String(form.get("dueDate")) || undefined, completed: false, createdAt: new Date().toISOString() };
    updateOperation(selected.id, { tasks: [...operationTasks(selected), task] }); setShowOperationTask(false);
  };
  const addOperationDocument = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const document: OperationDocument = { id: uid("document"), type: String(form.get("type")), title: String(form.get("title")), reference: String(form.get("reference")) || undefined, issuedAt: String(form.get("issuedAt")) || undefined, expiresAt: String(form.get("expiresAt")) || undefined, status: String(form.get("status")) as OperationDocument["status"], createdAt: new Date().toISOString() };
    updateOperation(selected.id, { documents: [...(selected.documents ?? []), document] }); setShowOperationDocument(false);
  };
  const completeOperationTask = (taskId: string) => { if (!selected) return; updateOperation(selected.id, { tasks: operationTasks(selected).map((task) => task.id === taskId ? { ...task, completed: !task.completed } : task) }); };

  const changeView = (next: View) => { window.history.pushState({}, "", viewUrl(next)); setView(next); setDetailId(null); setOperationsUrlState(window.location.search); setSidebarOpen(false); };
  const openOperations = (filters: Partial<OperationsFilters> = {}) => { const next = { ...operationsFiltersFromUrl(), ...filters }; const url = operationsUrl(next); window.history.pushState({}, "", url); setOperationsUrlState(window.location.search); setDetailId(null); setView("imports"); };
  const updateOperationsFilters = (filters: OperationsFilters) => { window.history.pushState({}, "", operationsUrl(filters)); setOperationsUrlState(window.location.search); };
  const openOperation = (id: string) => { window.history.pushState({}, "", `/operacoes/${id}${window.location.search}`); setSelectedId(id); setDetailId(id); setView("imports"); };
  const closeOperationDetail = () => { window.history.pushState({}, "", `/operacoes${window.location.search}`); setDetailId(null); };
  return <div className="app-shell">
    <aside className={`sidebar ${sidebarOpen ? "sidebar--open" : ""}`} aria-label="Navegação principal">
      <div className="brand"><span className="brand-mark" style={{ backgroundImage: `url(${brandMark})` }} role="img" aria-label="Exporta Brasil" /><span><strong>Exporta</strong><small>Brasil</small></span><button className="icon-button mobile-only" onClick={() => setSidebarOpen(false)} aria-label="Fechar menu"><X size={20} /></button></div>
      <nav>{navigation.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${view === id ? "is-active" : ""}`} onClick={() => changeView(id)}><Icon size={19} /><span>{label}</span>{id === "pending" && <b className="nav-count">3</b>}</button>)}</nav>
      <div className="sidebar-footer"><button className="nav-item" onClick={() => setShowUserManager(true)}><Settings size={19} /><span>Configurações</span></button><div className="user-card"><span className="avatar">{session.user.name.split(" ").map((part) => part[0]).slice(0, 2).join("")}</span><span><strong>{session.user.name}</strong><small>{session.user.role === "admin" ? "Administrador" : "Operador"}</small></span><button className="logout-button" onClick={onLogout}>Sair</button></div></div>
    </aside>
    {sidebarOpen && <button className="scrim" onClick={() => setSidebarOpen(false)} aria-label="Fechar menu" />}
    <main className="main-content">
      <header className="topbar"><button className="icon-button mobile-only" onClick={() => setSidebarOpen(true)} aria-label="Abrir menu"><Menu size={21} /></button><nav className="breadcrumb" aria-label="Caminho de navegação">{view === "dashboard" ? <strong>Início</strong> : <><button onClick={() => changeView("dashboard")}>Início</button><ChevronRight size={15} />{detailId && view === "imports" ? <><button onClick={closeOperationDetail}>Operações</button><ChevronRight size={15} /><strong>{selected?.reference}</strong></> : <strong>{navigation.find((item) => item.id === view)?.label}</strong>}</>}</nav><MarketPulse context={marketContext} error={marketContextError} /><div className="top-actions"><button className="icon-button" aria-label="Buscar"><Search size={19} /></button><button className="icon-button notification" aria-label="Notificações"><Bell size={19} /><i /></button><button className="icon-button" aria-label="Ajuda"><CircleHelp size={19} /></button></div></header>
      {view === "dashboard" && <Dashboard operations={operations} totalInProgress={totalInProgress} totalValue={totalValue} onOpen={() => openOperations()} onOpenChannel={(channel) => openOperations({ channel, page: 1 })} />}
       {view === "imports" && !detailId && <OperationsListView operations={operations} urlState={operationsUrlState} onFiltersChange={updateOperationsFilters} onNew={() => setShowNewImport(true)} onOpen={openOperation} />}
       {view === "imports" && detailId && selected && <OperationDetailPage selected={selected} onBack={closeOperationDetail} onAddItem={() => setShowNewItem(true)} onAddTimeline={() => setShowTimelineEntry(true)} onAddTask={() => setShowOperationTask(true)} onAddDocument={() => setShowOperationDocument(true)} onToggleTask={completeOperationTask} onUpdate={updateOperation} />}
       {view === "ports" && <PortsCatalogView facilities={portFacilities} state={portCatalogState} error={portCatalogError} onRetry={loadPortCatalog} />}
       {view === "customers" && <CustomersView customers={customers} operations={operations} onNew={() => { setEditingCustomer(null); setShowNewCustomer(true); }} onEdit={(customer) => { setEditingCustomer(customer); setShowNewCustomer(true); }} />}
       {["pending", "reports"].includes(view) && <Placeholder view={view} onNavigate={() => openOperations()} />}
    </main>
    <nav className="bottom-nav" aria-label="Navegação móvel">{navigation.slice(0, 4).map(({ id, label, icon: Icon }) => <button key={id} className={view === id ? "is-active" : ""} onClick={() => changeView(id)}><Icon size={19} /><span>{label}</span></button>)}</nav>
    {showNewImport && <Dialog title={showImportCustomerForm ? "Novo cliente" : showCustomerPicker ? "Selecionar cliente" : "Nova importação"} className="dialog--wide" onClose={() => { setShowNewImport(false); setShowCustomerPicker(false); setShowImportCustomerForm(false); setImportCustomerId(""); }}><div hidden={showCustomerPicker || showImportCustomerForm}><ImportForm customers={customers} customerId={importCustomerId} portFacilities={portFacilities} portCatalogState={portCatalogState} portCatalogError={portCatalogError} onRetryPorts={loadPortCatalog} onSelectCustomer={() => setShowCustomerPicker(true)} onNewCustomer={() => setShowImportCustomerForm(true)} onSubmit={createOperation} /></div>{showCustomerPicker && <CustomerPickerContent customers={customers} onBack={() => setShowCustomerPicker(false)} onNewCustomer={() => { setShowCustomerPicker(false); setShowImportCustomerForm(true); }} onSelect={(id) => { setImportCustomerId(id); setShowCustomerPicker(false); }} />}{showImportCustomerForm && <CustomerForm customer={null} onSubmit={saveImportCustomer} onLookup={lookupCompany} onAddressLookup={lookupAddress} onCancel={() => setShowImportCustomerForm(false)} />}</Dialog>}
    {showNewItem && <Dialog title="Adicionar produto" onClose={() => setShowNewItem(false)}><ItemForm onSubmit={addItem} /></Dialog>}
    {showTimelineEntry && <Dialog title="Registrar marco" onClose={() => setShowTimelineEntry(false)}><TimelineEntryForm onSubmit={addTimelineEntry} /></Dialog>}
    {showOperationTask && <Dialog title="Nova pendência" onClose={() => setShowOperationTask(false)}><OperationTaskForm onSubmit={addOperationTask} /></Dialog>}
    {showOperationDocument && <Dialog title="Registrar documento" onClose={() => setShowOperationDocument(false)}><OperationDocumentForm onSubmit={addOperationDocument} /></Dialog>}
    {showNewCustomer && <Dialog title={editingCustomer ? "Editar cliente" : "Novo cliente"} onClose={() => { setEditingCustomer(null); setShowNewCustomer(false); }}><CustomerForm customer={editingCustomer} onSubmit={saveCustomer} onLookup={lookupCompany} onAddressLookup={lookupAddress} /></Dialog>}
    {showUserManager && <UserManagerDialog token={session.token} onClose={() => setShowUserManager(false)} />}
  </div>;
}

function Dashboard({ operations, totalInProgress, totalValue, onOpen, onOpenChannel }: { operations: ImportOperation[]; totalInProgress: number; totalValue: number; onOpen: () => void; onOpenChannel: (channel: CustomsChannel) => void }) {
  const atPort = operations.filter((operation) => ["at_port", "customs"].includes(operation.status)).length;
  return <section className="page dashboard-page"><div className="page-heading"><div><p className="eyebrow">CENTRO DE CONTROLE</p><h1>Operações sob controle.</h1><p className="muted">Acompanhe custos, cargas e decisões que pedem atenção.</p></div><button className="button button--primary" onClick={onOpen}><ShipWheel size={18} /> Ver operações</button></div>
    <div className="metric-grid"><Metric icon={<Container />} label="Importações ativas" value={String(totalInProgress)} detail="processos em andamento" tone="blue" /><Metric icon={<MapPinned />} label="Cargas em porto" value={String(atPort)} detail="com atualização necessária" tone="amber" /><Metric icon={<ChartNoAxesCombined />} label="Custo projetado" value={money.format(totalValue)} detail="nas operações abertas" tone="green" /></div>
    <CustomsSignalOverview operations={operations} onOpenChannel={onOpenChannel} />
    <div className="dashboard-grid"><section className="panel"><div className="panel-header"><div><h2>Operações recentes</h2><p>Os processos que exigem acompanhamento.</p></div><button className="text-button" onClick={onOpen}>Ver todas</button></div><div className="activity-list">{operations.map((operation) => <button className="activity-row" key={operation.id} onClick={onOpen}><span className="activity-icon"><ShipWheel size={18} /></span><span><strong>{operation.reference}</strong><small>{operation.customer} · {operation.port}</small></span><StatusBadge status={operation.status} /><ChevronRight size={18} /></button>)}</div></section>
      <section className="panel attention-card"><div className="panel-header"><div><h2>Próxima decisão</h2><p>Uma pendência prioritária.</p></div><span className="urgency">Hoje</span></div><div className="attention-body"><span className="attention-icon"><ClipboardList size={22} /></span><div><strong>Validar documentação de desembaraço</strong><p>EB-2026-001 está em análise aduaneira no Porto de Santos.</p><button className="text-button" onClick={onOpen}>Abrir operação <ChevronRight size={15} /></button></div></div></section></div>
  </section>;
}

function OperationsListView({ operations, urlState, onFiltersChange, onNew, onOpen }: { operations: ImportOperation[]; urlState: string; onFiltersChange: (filters: OperationsFilters) => void; onNew: () => void; onOpen: (id: string) => void }) {
  const [filters, setFiltersState] = useState<OperationsFilters>(operationsFiltersFromUrl);
  useEffect(() => { setFiltersState(operationsFiltersFromUrl()); }, [urlState]);
  const setFilters = (changes: Partial<OperationsFilters>) => { const next = { ...filters, ...changes }; setFiltersState(next); onFiltersChange(next); };
  const { query, status, channel, sort, page } = filters;
  const hasActiveFilters = Boolean(query) || status !== "all" || channel !== "all" || sort !== "oldest" || page > 1;
  const pageSize = 8;
  const filtered = operations.filter((operation) => (!query || `${operation.reference} ${operation.customer} ${operation.supplier} ${operation.port}`.toLocaleLowerCase("pt-BR").includes(query.toLocaleLowerCase("pt-BR"))) && (status === "all" || operation.status === status) && (channel === "all" || operation.customsChannel === channel));
  const ordered = [...filtered].sort((a, b) => { const created = new Date(a.createdAt ?? a.updatedAt).getTime() - new Date(b.createdAt ?? b.updatedAt).getTime(); if (sort === "newest") return -created; if (sort === "updated") return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(); return created; });
  const totalPages = Math.max(1, Math.ceil(ordered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = ordered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return <section className="page operations-page"><div className="page-heading"><div><p className="eyebrow">GESTÃO DE IMPORTAÇÕES</p><h1>Operações</h1><p className="muted">Encontre uma operação, filtre a fila e abra um processo para trabalhar nos detalhes.</p></div><button className="button button--primary" onClick={onNew}><Plus size={18} /> Nova importação</button></div><section className="panel operations-list-panel"><div className="operations-toolbar"><label className="search-field"><Search size={17} /><input value={query} onChange={(event) => setFilters({ query: event.target.value, page: 1 })} placeholder="Buscar por referência, cliente ou porto" aria-label="Buscar operações" /></label><div className="operation-filters"><label><SlidersHorizontal size={15} /><span className="sr-only">Status</span><select value={status} onChange={(event) => setFilters({ status: event.target.value as ImportStatus | "all", page: 1 })}><option value="all">Todos os status</option>{Object.entries(importStatusMeta).map(([value, meta]) => <option key={value} value={value}>{meta.label}</option>)}</select></label><label><span className="sr-only">Canal aduaneiro</span><select value={channel} onChange={(event) => setFilters({ channel: event.target.value as CustomsSignal | "all", page: 1 })}><option value="all">Todos os canais</option>{Object.entries(customsChannelMeta).map(([value, meta]) => <option key={value} value={value}>{meta.label}</option>)}</select></label><label><span className="sr-only">Ordenação</span><select value={sort} onChange={(event) => setFilters({ sort: event.target.value as "oldest" | "newest" | "updated", page: 1 })}><option value="oldest">Mais antigas primeiro</option><option value="newest">Mais recentes primeiro</option><option value="updated">Atualizadas recentemente</option></select></label></div><button type="button" className="text-button operation-filters__clear" disabled={!hasActiveFilters} onClick={() => setFilters({ query: "", status: "all", channel: "all", sort: "oldest", page: 1 })}>Limpar filtros</button></div><div className="table-scroll"><table className="operations-table"><thead><tr><th>Referência</th><th>Cliente</th><th>Destino</th><th>ETA</th><th>Status</th><th>Canal</th><th>Criada em</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{visible.length === 0 ? <tr><td className="empty-cell" colSpan={8}>Nenhuma operação corresponde aos filtros.</td></tr> : visible.map((operation) => <tr key={operation.id}><td><strong>{operation.reference}</strong><small>{operation.supplier}</small></td><td>{operation.customer}</td><td><strong>{operation.port}</strong><small>{operation.container}</small></td><td>{formatDate(operation.eta)}</td><td><StatusBadge status={operation.status} /></td><td><CustomsChannelIndicator channel={operation.customsChannel} /></td><td>{new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium" }).format(new Date(operation.createdAt ?? operation.updatedAt))}</td><td><button className="table-detail-button" onClick={() => onOpen(operation.id)}>Ver detalhes <ChevronRight size={16} /></button></td></tr>)}</tbody></table></div><footer className="pagination"><span>{ordered.length === 0 ? "Nenhuma operação" : `${(currentPage - 1) * pageSize + 1}–${Math.min(currentPage * pageSize, ordered.length)} de ${ordered.length} operações`}</span><div><button className="icon-button" disabled={currentPage === 1} onClick={() => setFilters({ page: Math.max(1, currentPage - 1) })} aria-label="Página anterior"><ChevronLeft size={18} /></button><span>Página {currentPage} de {totalPages}</span><button className="icon-button" disabled={currentPage === totalPages} onClick={() => setFilters({ page: Math.min(totalPages, currentPage + 1) })} aria-label="Próxima página"><ChevronRight size={18} /></button></div></footer></section></section>;
}

function operationTimeline(operation: ImportOperation): OperationTimelineEntry[] {
  if (operation.timeline?.length) return operation.timeline;
  return [
    { id: "created", title: "Operação criada", description: "Processo aberto para acompanhamento operacional.", occurredAt: operation.createdAt, type: "milestone" },
    { id: "current-status", title: importStatusMeta[operation.status].label, description: portStatusMeta[operation.portStatus].detail, occurredAt: operation.updatedAt, type: "status" }
  ];
}
function operationTasks(operation: ImportOperation): OperationTask[] {
  if (operation.tasks?.length) return operation.tasks;
  return [{ id: "initial-task", title: "Revisar documentação da operação", assignee: "Operação", dueDate: operation.eta, completed: false, createdAt: operation.createdAt }];
}
function dayLabel(value?: string) { return value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short" }).format(new Date(`${value.slice(0, 10)}T12:00:00`)) : "Sem prazo"; }

function OperationDetailPage({ selected, onBack, onAddItem, onAddTimeline, onAddTask, onAddDocument, onToggleTask, onUpdate }: { selected: ImportOperation; onBack: () => void; onAddItem: () => void; onAddTimeline: () => void; onAddTask: () => void; onAddDocument: () => void; onToggleTask: (taskId: string) => void; onUpdate: (id: string, changes: Partial<ImportOperation>) => void }) {
  const calculated = calculateImport(selected);
  const tasks = operationTasks(selected);
  const documents = selected.documents ?? [];
  return <section className="page operations-page operation-detail-page"><div className="detail-heading"><button className="back-button" onClick={onBack}><ArrowLeft size={17} /> Todas as operações</button><p className="eyebrow">DETALHE DA OPERAÇÃO</p></div><OperationHeader operation={selected} onUpdate={onUpdate} /><div className="summary-grid"><Summary emphasis="primary" label="Custo total projetado" value={money.format(calculated.totalCost)} detail="estimativa atual da operação" /><Summary label="Pendências abertas" value={String(tasks.filter((task) => !task.completed).length)} detail="tarefas para concluir" /><Summary label="Documentos" value={String(documents.length)} detail={`${documents.filter((document) => document.status === "available").length} disponíveis`} /></div><section className="operation-workspace"><section className="panel timeline-panel"><div className="panel-header"><div><h2>Linha do tempo</h2><p>Marcos e atualizações registrados na operação.</p></div><button className="button button--secondary" onClick={onAddTimeline}><Plus size={17} /> Registrar marco</button></div><OperationTimeline entries={operationTimeline(selected)} /></section><section className="panel tasks-panel"><div className="panel-header"><div><h2>Pendências</h2><p>Controle de responsáveis e prazos.</p></div><button className="button button--secondary" onClick={onAddTask}><Plus size={17} /> Nova pendência</button></div><OperationTasks tasks={tasks} onToggle={onToggleTask} /></section></section><section className="panel documents-panel"><div className="panel-header"><div><h2>Documentos</h2><p>Referências, validade e disponibilidade da documentação do processo.</p></div><button className="button button--secondary" onClick={onAddDocument}><Upload size={17} /> Registrar documento</button></div><OperationDocuments documents={documents} /></section><section className="panel"><div className="panel-header"><div><h2>Produtos da importação</h2><p>O custo unitário já inclui rateio e tributos.</p></div><button className="button button--secondary" onClick={onAddItem}><PackagePlus size={17} /> Adicionar item</button></div><ProductsTable calculated={calculated} /></section><CostsForm operation={selected} calculated={calculated} onUpdate={onUpdate} /></section>;
}

function OperationTimeline({ entries }: { entries: OperationTimelineEntry[] }) { const ordered = [...entries].sort((left, right) => new Date(right.occurredAt).getTime() - new Date(left.occurredAt).getTime()); return <ol className="operation-timeline">{ordered.map((entry) => <li key={entry.id} data-type={entry.type}><span><CalendarClock size={15} /></span><div><time dateTime={entry.occurredAt}>{new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(entry.occurredAt))}</time><strong>{entry.title}</strong>{entry.description && <p>{entry.description}</p>}</div></li>)}</ol>; }
function OperationTasks({ tasks, onToggle }: { tasks: OperationTask[]; onToggle: (taskId: string) => void }) { const ordered = [...tasks].sort((left, right) => Number(left.completed) - Number(right.completed) || (left.dueDate ?? "9999").localeCompare(right.dueDate ?? "9999")); return <div className="operation-tasks">{ordered.map((task) => <div className={task.completed ? "is-completed" : ""} key={task.id}><button type="button" onClick={() => onToggle(task.id)} aria-label={task.completed ? `Reabrir ${task.title}` : `Concluir ${task.title}`}>{task.completed ? <CheckCircle2 size={18} /> : <span />}</button><span><strong>{task.title}</strong><small>{task.assignee || "Sem responsável"} · {dayLabel(task.dueDate)}</small></span>{!task.completed && task.dueDate && <b>{dayLabel(task.dueDate)}</b>}</div>)}</div>; }
function OperationDocuments({ documents }: { documents: OperationDocument[] }) { if (!documents.length) return <div className="documents-empty"><FileText size={22} /><p>Registre os documentos recebidos para acompanhar validade e disponibilidade.</p></div>; return <div className="table-scroll"><table className="documents-table"><thead><tr><th>Documento</th><th>Referência</th><th>Emissão</th><th>Validade</th><th>Situação</th></tr></thead><tbody>{documents.map((document) => <tr key={document.id}><td><strong>{document.title}</strong><small>{document.type}</small></td><td>{document.reference || "—"}</td><td>{dayLabel(document.issuedAt)}</td><td>{dayLabel(document.expiresAt)}</td><td><span className={`document-status document-status--${document.status}`}>{document.status === "available" ? "Disponível" : document.status === "expired" ? "Vencido" : "Pendente"}</span></td></tr>)}</tbody></table></div>; }
function OperationHeader({ operation, onUpdate }: { operation: ImportOperation; onUpdate: (id: string, changes: Partial<ImportOperation>) => void }) {
  return <header className="operation-header panel"><div><p className="eyebrow">{operation.reference}</p><h2>{operation.customer}</h2><p className="muted">{operation.supplier} · {operation.container}</p></div><div className="operation-status"><label>Status da operação<select value={operation.status} onChange={(event) => onUpdate(operation.id, { status: event.target.value as ImportStatus })}>{Object.entries(importStatusMeta).map(([value, meta]) => <option value={value} key={value}>{meta.label}</option>)}</select></label><StatusBadge status={operation.status} /></div><div className="port-progress"><div><span className="port-pin"><MapPinned size={18} /></span><span><strong>{operation.port}</strong><small>ETA {formatDate(operation.eta)}</small></span></div><label>Status portuário<select value={operation.portStatus} onChange={(event) => onUpdate(operation.id, { portStatus: event.target.value as PortStatus })}>{Object.entries(portStatusMeta).map(([value, meta]) => <option value={value} key={value}>{meta.label}</option>)}</select></label></div><div className="customs-channel-row"><CustomsLight channel={operation.customsChannel} /><div><strong>Canal aduaneiro</strong><p>{customsChannelMeta[operation.customsChannel].detail}</p></div><label><span className="sr-only">Canal aduaneiro</span><select value={operation.customsChannel} onChange={(event) => onUpdate(operation.id, { customsChannel: event.target.value as CustomsSignal })}>{Object.entries(customsChannelMeta).map(([value, meta]) => <option value={value} key={value}>{meta.label}</option>)}</select><small>Atualização manual</small></label></div></header>;
}

function CustomsLight({ channel, compact = false, active = true }: { channel: CustomsSignal; compact?: boolean; active?: boolean }) { const meta = customsChannelMeta[channel]; return <div className={`customs-light${compact ? " customs-light--compact" : ""}`} role="img" aria-label={active ? `${meta.label}: ${meta.detail}` : "Farol aduaneiro"}><span className="customs-light__lens customs-light__lens--green" data-active={active && channel === "green"} /><span className="customs-light__lens customs-light__lens--yellow" data-active={active && channel === "yellow"} /><span className="customs-light__lens customs-light__lens--red" data-active={active && channel === "red"} /><span className="customs-light__lens customs-light__lens--gray" data-active={active && (channel === "gray" || channel === "pending")} /></div>; }

function CustomsChannelIndicator({ channel }: { channel: CustomsSignal }) { const meta = customsChannelMeta[channel]; return <span className={`customs-channel-indicator customs-channel-indicator--${channel}`} title={`${meta.label}: ${meta.detail}`}><span aria-hidden="true" /><span>{channel === "pending" ? "Aguardando" : meta.label.replace("Canal ", "")}</span></span>; }

function CustomsSignalOverview({ operations, onOpenChannel }: { operations: ImportOperation[]; onOpenChannel: (channel: CustomsChannel) => void }) { const channels: CustomsChannel[] = ["green", "yellow", "red", "gray"]; const pending = operations.filter((operation) => operation.customsChannel === "pending").length; return <section className="panel customs-overview"><div className="customs-overview__intro"><CustomsLight channel="pending" active={false} /><div><h2>Farol aduaneiro</h2><p>Operações por canal de conferência. A cor é sempre acompanhada pelo nome e pela etapa aplicável.</p>{pending > 0 && <small>{pending} aguardando parametrização</small>}</div></div><div className="customs-overview__counts">{channels.map((channel) => { const meta = customsChannelMeta[channel]; const count = operations.filter((operation) => operation.customsChannel === channel).length; return <button className={`customs-count customs-count--${channel}`} type="button" key={channel} onClick={() => onOpenChannel(channel)} aria-label={`Ver operações no ${meta.label}`}><span className="customs-count__dot" aria-hidden="true" /><span>{meta.label}</span><strong>{count}</strong><small>{meta.detail}</small></button>; })}</div></section>; }

function PortsCatalogView({ facilities, state, error, onRetry }: { facilities: PortFacility[]; state: "idle" | "loading" | "ready" | "error"; error: string; onRetry: () => void }) {
  const [query, setQuery] = useState("");
  const [selectedState, setSelectedState] = useState("all");
  const [selectedType, setSelectedType] = useState("all");
  const [page, setPage] = useState(1);
  const pageSize = 12;
  const states = [...new Set(facilities.map((facility) => facility.state))].sort();
  const types = [...new Set(facilities.map((facility) => facility.type))].sort();
  const filtered = facilities.filter((facility) => (!query || `${facility.name} ${facility.municipality} ${facility.state}`.toLocaleLowerCase("pt-BR").includes(query.toLocaleLowerCase("pt-BR"))) && (selectedState === "all" || facility.state === selectedState) && (selectedType === "all" || facility.type === selectedType));
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const resetPage = () => setPage(1);

  return <section className="page ports-catalog-page"><div className="page-heading"><div><p className="eyebrow">DADOS DE REFERÊNCIA</p><h1>Instalações portuárias</h1><p className="muted">Catálogo oficial para padronizar portos e terminais nas operações de importação.</p></div><a className="button button--secondary" href="https://www.gov.br/antaq/pt-br/assuntos/instalacoes-portuarias" target="_blank" rel="noreferrer">Fonte: ANTAQ</a></div><section className="panel ports-catalog-panel"><div className="ports-catalog-context"><span><MapPinned size={18} aria-hidden="true" /><strong>{facilities.length || "—"}</strong> instalações publicadas</span><span>Referência administrativa; o andamento da carga é registrado dentro de cada operação.</span></div><div className="operations-toolbar ports-toolbar"><label className="search-field"><Search size={17} aria-hidden="true" /><input value={query} onChange={(event) => { setQuery(event.target.value); resetPage(); }} placeholder="Buscar por instalação, cidade ou UF" aria-label="Buscar instalações portuárias" /></label><div className="operation-filters"><label><span className="sr-only">UF</span><select value={selectedState} onChange={(event) => { setSelectedState(event.target.value); resetPage(); }}><option value="all">Todas as UFs</option>{states.map((item) => <option value={item} key={item}>{item}</option>)}</select></label><label><span className="sr-only">Tipo</span><select value={selectedType} onChange={(event) => { setSelectedType(event.target.value); resetPage(); }}><option value="all">Todos os tipos</option>{types.map((item) => <option value={item} key={item}>{item}</option>)}</select></label></div></div>{state === "loading" && <div className="catalog-message" role="status">Consultando o catálogo de instalações portuárias…</div>}{state === "error" && <div className="catalog-message catalog-message--error" role="alert"><span>{error}</span><button className="button button--secondary" onClick={onRetry}>Tentar novamente</button></div>}{state === "ready" && <><div className="table-scroll"><table className="ports-table"><thead><tr><th>Instalação</th><th>Localização</th><th>Tipo</th><th>Gestão</th><th>Situação</th></tr></thead><tbody>{visible.length === 0 ? <tr><td className="empty-cell" colSpan={5}>Nenhuma instalação corresponde aos filtros.</td></tr> : visible.map((facility) => <tr key={facility.id}><td><strong>{facility.name}</strong><small>ID ANTAQ {facility.id}</small></td><td><strong>{facility.municipality}</strong><small>{facility.state}</small></td><td><span className="facility-type">{facility.type}</span></td><td>{facility.management || "Não informado"}</td><td><span className="facility-status">{facility.operationalStatus || "Não informado"}</span></td></tr>)}</tbody></table></div><footer className="pagination"><span>{filtered.length === 0 ? "Nenhuma instalação" : `${(currentPage - 1) * pageSize + 1}–${Math.min(currentPage * pageSize, filtered.length)} de ${filtered.length} instalações`}</span><div><button className="icon-button" disabled={currentPage === 1} onClick={() => setPage((value) => Math.max(1, value - 1))} aria-label="Página anterior"><ChevronLeft size={18} /></button><span>Página {currentPage} de {totalPages}</span><button className="icon-button" disabled={currentPage === totalPages} onClick={() => setPage((value) => Math.min(totalPages, value + 1))} aria-label="Próxima página"><ChevronRight size={18} /></button></div></footer></>}</section></section>;
}

function ProductsTable({ calculated }: { calculated: ReturnType<typeof calculateImport> }) { return <div className="table-scroll"><table><thead><tr><th>Produto / NCM</th><th>Qtd.</th><th>FOB</th><th>Rateio</th><th>Tributos</th><th>Custo unitário</th></tr></thead><tbody>{calculated.items.length === 0 ? <tr><td colSpan={6} className="empty-cell">Adicione os produtos para calcular os custos.</td></tr> : calculated.items.map((item) => <tr key={item.id}><td><strong>{item.name}</strong><small>{item.ncm}</small></td><td>{item.quantity}</td><td>{money.format(item.itemFob)}</td><td>{money.format(item.allocatedExpenses)}</td><td>{money.format(item.ii + item.ipi)}</td><td><strong>{money.format(item.unitCost)}</strong></td></tr>)}</tbody></table></div>; }

function CostsForm({ operation, calculated, onUpdate }: { operation: ImportOperation; calculated: ReturnType<typeof calculateImport>; onUpdate: (id: string, changes: Partial<ImportOperation>) => void }) { return <section className="panel costs-panel"><div className="panel-header"><div><h2>Valores e rateio</h2><p>Os custos logísticos são distribuídos proporcionalmente ao FOB de cada item.</p></div></div><div className="cost-inputs"><NumberField label="Câmbio (R$/US$)" value={operation.exchangeRate} step="0.01" onChange={(value) => onUpdate(operation.id, { exchangeRate: value })} /><NumberField label="Frete internacional" value={operation.freightBrl} onChange={(value) => onUpdate(operation.id, { freightBrl: value })} prefix="R$" /><NumberField label="Seguro" value={operation.insuranceBrl} onChange={(value) => onUpdate(operation.id, { insuranceBrl: value })} prefix="R$" /><NumberField label="Despesas portuárias" value={operation.portExpensesBrl} onChange={(value) => onUpdate(operation.id, { portExpensesBrl: value })} prefix="R$" /></div><div className="cost-result"><div className="cost-breakdown"><span>Base FOB <strong>{money.format(calculated.fobBrl)}</strong></span><span>Custos rateados <strong>{money.format(calculated.baseExpenses)}</strong></span><span>Tributos <strong>{money.format(calculated.taxes)}</strong></span></div><div className="cost-total"><span>Total projetado</span><strong>{money.format(calculated.totalCost)}</strong><small>estimativa atual</small></div></div></section>; }

function NumberField({ label, value, onChange, prefix, step = "1" }: { label: string; value: number; onChange: (value: number) => void; prefix?: string; step?: string }) { return <label className="field"><span>{label}</span><div className="number-input">{prefix && <b>{prefix}</b>}<input type="number" min="0" step={step} value={value} onChange={(event) => onChange(Number(event.target.value) || 0)} /></div></label>; }
function Summary({ label, value, detail, emphasis }: { label: string; value: string; detail: string; emphasis?: "primary" }) { return <div className={`summary-card${emphasis ? ` summary-card--${emphasis}` : ""}`}><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>; }
function Metric({ icon, label, value, detail, tone }: { icon: ReactNode; label: string; value: string; detail: string; tone: string }) { return <section className={`metric-card tone-${tone}`}><span className="metric-icon">{icon}</span><p>{label}</p><strong>{value}</strong><small>{detail}</small></section>; }
function StatusBadge({ status }: { status: ImportStatus }) { const meta = importStatusMeta[status]; return <span className={`status status--${meta.tone}`}>{meta.label}</span>; }
function Dialog({ title, onClose, children, className }: { title: string; onClose: () => void; children: ReactNode; className?: string }) { return <DialogRoot open onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent className={className} aria-describedby={undefined}><header><DialogTitle asChild><h2>{title}</h2></DialogTitle><DialogClose asChild><button className="icon-button" aria-label="Fechar"><X size={20} /></button></DialogClose></header>{children}</DialogContent></DialogRoot>; }
function ImportForm({ customers, customerId, portFacilities, portCatalogState, portCatalogError, onRetryPorts, onSelectCustomer, onNewCustomer, onSubmit }: { customers: Customer[]; customerId: string; portFacilities: PortFacility[]; portCatalogState: "idle" | "loading" | "ready" | "error"; portCatalogError: string; onRetryPorts: () => void; onSelectCustomer: () => void; onNewCustomer: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { const customer = customers.find((item) => item.id === customerId); return <form className="form-grid" onSubmit={onSubmit}><label className="field"><span>Referência</span><input name="reference" placeholder="EB-2026-003" /></label><div className="field"><span>Cliente</span><input name="customerId" value={customerId} type="hidden" required readOnly /><div className="customer-picker"><button className="customer-picker__trigger" type="button" onClick={onSelectCustomer}><span>{customer ? customer.tradeName || customer.legalName : "Selecionar cliente"}</span><ChevronRight size={17} /></button><button className="text-button" type="button" onClick={onNewCustomer}><Plus size={15} /> Novo cliente</button></div></div><label className="field"><span>Fornecedor</span><input name="supplier" required placeholder="Fornecedor internacional" /></label><label className="field"><span>Porto de destino</span><select name="port" required defaultValue="" disabled={portCatalogState === "loading" || portCatalogState === "idle"}><option value="" disabled>{portCatalogState === "loading" || portCatalogState === "idle" ? "Carregando portos cadastrados…" : "Selecione um porto ou terminal"}</option>{portFacilities.map((facility) => <option key={facility.id} value={facility.name}>{facility.name} · {facility.municipality}/{facility.state}</option>)}</select>{portCatalogState === "error" && <span className="field-error">{portCatalogError} <button className="text-button" type="button" onClick={onRetryPorts}>Tentar novamente</button></span>}</label><label className="field"><span>Contêiner</span><input name="container" required placeholder="ABCD 123456-7" /></label><label className="field"><span>ETA</span><input name="eta" type="date" required /></label><button className="button button--primary form-submit" type="submit" disabled={portCatalogState !== "ready"}><Plus size={18} /> Criar importação</button></form>; }
function CustomerPickerContent({ customers, onBack, onSelect, onNewCustomer }: { customers: Customer[]; onBack: () => void; onSelect: (id: string) => void; onNewCustomer: () => void }) { const [query, setQuery] = useState(""); const visible = customers.filter((customer) => customer.status === "active" && `${customer.legalName} ${customer.tradeName} ${customer.taxId}`.toLowerCase().includes(query.toLowerCase())); return <div className="customer-picker-dialog"><div className="customer-picker-dialog__toolbar"><button className="text-button" type="button" onClick={onBack}><ArrowLeft size={16} /> Voltar</button><label className="search-field"><Search size={17} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por empresa ou CNPJ" aria-label="Buscar clientes" /></label><button className="text-button" type="button" onClick={onNewCustomer}><Plus size={16} /> Novo cliente</button></div><div className="customer-picker-dialog__list">{visible.length === 0 ? <p className="customer-picker-dialog__empty">Nenhum cliente ativo corresponde à busca.</p> : visible.map((customer) => <button type="button" key={customer.id} onClick={() => onSelect(customer.id)}><span><strong>{customer.tradeName || customer.legalName}</strong><small>{customer.legalName} · {customer.taxId}</small></span><ChevronRight size={18} /></button>)}</div></div>; }
function UserManagerDialog({ token, onClose }: { token: string; onClose: () => void }) { const [users, setUsers] = useState<SessionUser[]>([]); const [message, setMessage] = useState(""); const load = () => fetch(`${apiUrl}/api/users`, { headers: { authorization: `Bearer ${token}` } }).then((response) => response.json()).then((data: SessionUser[] | { message?: string }) => Array.isArray(data) ? setUsers(data) : setMessage(data.message || "Não foi possível carregar usuários.")); useEffect(() => { load(); }, []); const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await fetch(`${apiUrl}/api/users`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify({ name: form.get("name"), email: form.get("email"), role: form.get("role"), initialPassword: form.get("initialPassword") }) }); const payload = await response.json() as SessionUser | { message?: string }; if (!response.ok) return setMessage("message" in payload ? payload.message || "Não foi possível criar o usuário." : "Não foi possível criar o usuário."); setUsers((current) => [...current, payload as SessionUser]); event.currentTarget.reset(); setMessage("Usuário criado. A troca de senha será exigida no primeiro acesso."); }; return <Dialog title="Usuários e acessos" className="dialog--wide" onClose={onClose}><div className="user-manager"><form className="form-grid" onSubmit={create}><label className="field"><span>Nome</span><input name="name" required /></label><label className="field"><span>E-mail</span><input name="email" type="email" required /></label><label className="field"><span>Perfil</span><select name="role" defaultValue="operator"><option value="operator">Operador</option><option value="admin">Administrador</option></select></label><label className="field"><span>Senha inicial</span><input name="initialPassword" type="password" minLength={8} required /></label><button className="button button--primary form-submit"><Plus size={18} /> Criar usuário</button></form>{message && <p className="user-manager__message">{message}</p>}<div className="user-manager__list">{users.map((user) => <div key={user.id}><span><strong>{user.name}</strong><small>{user.email}</small></span><small>{user.mustChangePassword ? "Aguardando primeiro acesso" : user.role === "admin" ? "Administrador" : "Operador"}</small></div>)}</div></div></Dialog>; }
function TimelineEntryForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="form-grid" onSubmit={onSubmit}><label className="field full"><span>Marco</span><input name="title" required placeholder="Ex.: Conhecimento de embarque recebido" autoFocus /></label><label className="field"><span>Data e hora</span><input name="occurredAt" type="datetime-local" required defaultValue={new Date().toISOString().slice(0, 16)} /></label><label className="field"><span>Tipo</span><select name="type" defaultValue="milestone"><option value="milestone">Marco operacional</option><option value="status">Atualização de status</option><option value="note">Observação</option></select></label><label className="field full"><span>Detalhes</span><input name="description" placeholder="Contexto para a equipe" /></label><button className="button button--primary form-submit"><Plus size={18} /> Registrar marco</button></form>; }
function OperationTaskForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="form-grid" onSubmit={onSubmit}><label className="field full"><span>Pendência</span><input name="title" required placeholder="Ex.: Conferir invoice antes do registro" autoFocus /></label><label className="field"><span>Responsável</span><input name="assignee" placeholder="Nome ou equipe" /></label><label className="field"><span>Prazo</span><input name="dueDate" type="date" /></label><button className="button button--primary form-submit"><Plus size={18} /> Criar pendência</button></form>; }
function OperationDocumentForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="form-grid" onSubmit={onSubmit}><label className="field"><span>Tipo</span><select name="type" defaultValue="Commercial Invoice"><option>Commercial Invoice</option><option>Packing List</option><option>Bill of Lading</option><option>Licença de Importação</option><option>Comprovante de pagamento</option><option>Outro</option></select></label><label className="field"><span>Situação</span><select name="status" defaultValue="available"><option value="available">Disponível</option><option value="pending">Pendente</option><option value="expired">Vencido</option></select></label><label className="field full"><span>Nome do documento</span><input name="title" required placeholder="Ex.: CI 2026-091 — Ningbo Horizon" autoFocus /></label><label className="field"><span>Referência</span><input name="reference" placeholder="Número do documento" /></label><label className="field"><span>Data de emissão</span><input name="issuedAt" type="date" /></label><label className="field"><span>Validade</span><input name="expiresAt" type="date" /></label><button className="button button--primary form-submit"><FileText size={18} /> Registrar documento</button></form>; }
function ItemForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="form-grid" onSubmit={onSubmit}><label className="field full"><span>Produto</span><input name="name" required placeholder="Descrição comercial" /></label><label className="field"><span>NCM</span><input name="ncm" required inputMode="numeric" placeholder="00000000" /></label><label className="field"><span>Quantidade</span><input name="quantity" required type="number" min="1" /></label><label className="field"><span>Preço unitário (US$)</span><input name="unitPriceUsd" required type="number" min="0" step="0.01" /></label><label className="field"><span>Peso bruto unitário (kg)</span><input name="grossWeightKg" required type="number" min="0" step="0.01" /></label><label className="field"><span>II (%)</span><input name="iiRate" required type="number" min="0" step="0.01" defaultValue="18" /></label><label className="field"><span>IPI (%)</span><input name="ipiRate" required type="number" min="0" step="0.01" defaultValue="0" /></label><button className="button button--primary form-submit" type="submit"><PackagePlus size={18} /> Adicionar produto</button></form>; }
function CustomerForm({ customer, onSubmit, onLookup, onAddressLookup, onCancel }: { customer: Customer | null; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onLookup: (taxId: string) => Promise<CompanyLookup>; onAddressLookup: (postalCode: string) => Promise<AddressLookup>; onCancel?: () => void }) {
  const formRef = useRef<HTMLFormElement>(null);
  const [activeTab, setActiveTab] = useState<"main" | "address" | "contact">("main");
  const [taxId, setTaxId] = useState(() => formatCnpj(customer?.taxId ?? ""));
  const [postalCode, setPostalCode] = useState(() => formatCep(customer?.postalCode ?? ""));
  const [lookupMessage, setLookupMessage] = useState("");
  const [addressMessage, setAddressMessage] = useState("");
  const [isLookingUp, setIsLookingUp] = useState(false);
  const [isLookingUpAddress, setIsLookingUpAddress] = useState(false);
  const fill = (name: keyof CompanyLookup | keyof AddressLookup, value?: string) => { const field = formRef.current?.elements.namedItem(name) as HTMLInputElement | null; if (field && value) field.value = value; };
  const lookup = async (value: string) => {
    const raw = cnpjRaw(value);
    if (raw.length < 14) return setLookupMessage("Informe os 14 caracteres do CNPJ para consultar a Receita Federal.");
    if (!isValidCnpj(raw)) return setLookupMessage("CNPJ inválido. Confira os dígitos verificadores.");
    setIsLookingUp(true); setLookupMessage("Consultando dados cadastrais…");
    try { const company = await onLookup(raw); (Object.entries(company) as Array<[keyof CompanyLookup, string | undefined]>).forEach(([name, fieldValue]) => fill(name, fieldValue)); setLookupMessage("Dados cadastrais preenchidos. Revise antes de salvar."); }
    catch (error) { setLookupMessage(error instanceof Error ? error.message : "Não foi possível consultar o CNPJ."); }
    finally { setIsLookingUp(false); }
  };
  const lookupAddress = async (value: string) => {
    const raw = cepRaw(value);
    if (raw.length < 8) return setAddressMessage("Informe os 8 dígitos do CEP para consultar o endereço.");
    setIsLookingUpAddress(true); setAddressMessage("Consultando endereço…");
    try { const address = await onAddressLookup(raw); (Object.entries(address) as Array<[keyof AddressLookup, string | undefined]>).forEach(([name, fieldValue]) => fill(name, fieldValue)); setPostalCode(formatCep(address.postalCode || raw)); setAddressMessage(""); }
    catch (error) { setAddressMessage(error instanceof Error ? error.message : "Não foi possível consultar o CEP."); }
    finally { setIsLookingUpAddress(false); }
  };
  const changeTaxId = (value: string) => { const formatted = formatCnpj(value); setTaxId(formatted); setLookupMessage(""); if (cnpjRaw(formatted).length === 14) void lookup(formatted); };
  const changePostalCode = (value: string) => { const formatted = formatCep(value); setPostalCode(formatted); setAddressMessage(""); if (cepRaw(formatted).length === 8) void lookupAddress(formatted); };
  const submit = (event: FormEvent<HTMLFormElement>) => { if (!isValidCnpj(taxId)) { event.preventDefault(); setActiveTab("main"); setLookupMessage("Informe um CNPJ válido antes de salvar."); return; } onSubmit(event); };
  const tab = (id: "main" | "address" | "contact", label: string, position: number) => <button className={`customer-form__tab ${activeTab === id ? "is-active" : ""}`} type="button" role="tab" aria-selected={activeTab === id} aria-controls={`customer-panel-${id}`} id={`customer-tab-${id}`} onClick={() => setActiveTab(id)}><b>{position}</b>{label}</button>;
  return <form ref={formRef} className="form-grid customer-form" onSubmit={submit}>{onCancel && <button className="text-button form-back" type="button" onClick={onCancel}><ArrowLeft size={16} /> Voltar à importação</button>}<div className="customer-form__tabs" role="tablist" aria-label="Etapas do cadastro do cliente">{tab("main", "Dados principais", 1)}{tab("address", "Endereço", 2)}{tab("contact", "Contato", 3)}</div><div className="customer-form__panel full" id="customer-panel-main" role="tabpanel" aria-labelledby="customer-tab-main" hidden={activeTab !== "main"}><p className="customer-form__hint">Comece pela identificação da empresa. A consulta oficial preenche os dados disponíveis.</p><div className="customer-form__fields"><label className="field full"><span>CNPJ</span><input name="taxId" required value={taxId} onChange={(event) => changeTaxId(event.target.value)} onBlur={() => void lookup(taxId)} inputMode="text" autoCapitalize="characters" autoComplete="off" maxLength={18} placeholder="12.345.678/0001-95 ou 12.ABC.345/01DE-35" aria-describedby="cnpj-help" />{lookupMessage && <small id="cnpj-help" className={lookupMessage.startsWith("CNPJ inválido") || lookupMessage.startsWith("Informe um CNPJ") || lookupMessage.startsWith("Não foi") ? "field-error" : "field-help"} aria-live="polite">{isLookingUp ? "Consultando dados cadastrais…" : lookupMessage}</small>}</label><label className="field full"><span>Razão social</span><input name="legalName" required defaultValue={customer?.legalName} placeholder="Empresa Importadora Ltda." /></label><label className="field"><span>Nome fantasia</span><input name="tradeName" defaultValue={customer?.tradeName} placeholder="Como será exibido no sistema" /></label><label className="field"><span>Situação cadastral</span><input name="registrationStatus" defaultValue={customer?.registrationStatus} placeholder="Preenchida pela consulta" /></label></div></div><div className="customer-form__panel full" id="customer-panel-address" role="tabpanel" aria-labelledby="customer-tab-address" hidden={activeTab !== "address"}><p className="customer-form__hint">Digite o CEP para preencher o endereço pelo ViaCEP. Todos os campos continuam editáveis.</p><div className="customer-form__fields"><label className="field"><span>CEP</span><input name="postalCode" value={postalCode} onChange={(event) => changePostalCode(event.target.value)} onBlur={() => void lookupAddress(postalCode)} inputMode="numeric" autoComplete="postal-code" maxLength={9} placeholder="00000-000" aria-describedby="cep-help" />{addressMessage && <small id="cep-help" className={addressMessage.startsWith("CEP não") || addressMessage.startsWith("Não foi") ? "field-error" : "field-help"} aria-live="polite">{isLookingUpAddress ? "Consultando endereço…" : addressMessage}</small>}</label><label className="field"><span>Número</span><input name="number" defaultValue={customer?.number} placeholder="Número" /></label><label className="field full"><span>Logradouro</span><input name="street" defaultValue={customer?.street} placeholder="Rua, avenida ou rodovia" autoComplete="address-line1" /></label><label className="field"><span>Complemento</span><input name="complement" defaultValue={customer?.complement} placeholder="Sala, bloco ou referência" autoComplete="address-line2" /></label><label className="field"><span>Bairro</span><input name="district" defaultValue={customer?.district} placeholder="Bairro" autoComplete="address-level3" /></label><label className="field"><span>Cidade</span><input name="city" defaultValue={customer?.city} placeholder="Cidade" autoComplete="address-level2" /></label><label className="field"><span>UF</span><input name="state" defaultValue={customer?.state} maxLength={2} autoCapitalize="characters" placeholder="SP" autoComplete="address-level1" /></label></div></div><div className="customer-form__panel full" id="customer-panel-contact" role="tabpanel" aria-labelledby="customer-tab-contact" hidden={activeTab !== "contact"}><p className="customer-form__hint">Defina a pessoa e os canais que receberão atualizações da operação.</p><div className="customer-form__fields"><label className="field full"><span>Responsável</span><input name="contactName" defaultValue={customer?.contactName} placeholder="Nome do contato" autoComplete="name" /></label><label className="field"><span>E-mail</span><input name="email" type="email" defaultValue={customer?.email} placeholder="contato@empresa.com.br" autoComplete="email" /></label><label className="field"><span>Telefone</span><input name="phone" type="tel" defaultValue={customer?.phone} placeholder="+55 11 99999-9999" autoComplete="tel" /></label></div></div><div className="customer-form__actions full"><button className="button button--secondary" type="button" onClick={() => setActiveTab(activeTab === "main" ? "contact" : activeTab === "address" ? "main" : "address")}>Anterior</button>{activeTab !== "contact" ? <button className="button button--primary" type="button" onClick={() => setActiveTab(activeTab === "main" ? "address" : "contact")}>Continuar</button> : <button className="button button--primary" type="submit"><Users size={18} /> {customer ? "Salvar alterações" : "Salvar cliente"}</button>}</div></form>;
}
function CustomersView({ customers, operations, onNew, onEdit }: { customers: Customer[]; operations: ImportOperation[]; onNew: () => void; onEdit: (customer: Customer) => void }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState<"operations" | "name" | "newest">("operations");
  const [status, setStatus] = useState<Customer["status"] | "all">("all");
  const operationCount = (customer: Customer) => operations.filter((operation) => operation.customerId === customer.id || operation.customer === customer.tradeName).length;
  const visibleCustomers = customers.filter((customer) => (status === "all" || customer.status === status) && `${customer.legalName} ${customer.tradeName} ${customer.taxId}`.toLowerCase().includes(query.toLowerCase())).sort((left, right) => {
    if (sort === "operations") return operationCount(right) - operationCount(left) || left.legalName.localeCompare(right.legalName, "pt-BR");
    if (sort === "newest") return new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime();
    return (left.tradeName || left.legalName).localeCompare(right.tradeName || right.legalName, "pt-BR");
  });
  return <section className="page"><div className="page-heading"><div><p className="eyebrow">CADASTRO E RELACIONAMENTO</p><h1>Clientes</h1><p className="muted">Empresas vinculadas às operações de importação.</p></div><button className="button button--primary" onClick={onNew}><Plus size={18} /> Novo cliente</button></div><section className="panel customers-panel"><div className="customers-toolbar"><label className="search-field"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por empresa ou CNPJ" aria-label="Buscar clientes" /></label><label className="customers-sort"><span>Status</span><select value={status} onChange={(event) => setStatus(event.target.value as Customer["status"] | "all")} aria-label="Filtrar clientes por status"><option value="all">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select></label><label className="customers-sort"><span>Ordenar</span><select value={sort} onChange={(event) => setSort(event.target.value as "operations" | "name" | "newest")} aria-label="Ordenar clientes"><option value="operations">Mais operações</option><option value="name">Nome da empresa</option><option value="newest">Cadastro mais recente</option></select></label><span>{visibleCustomers.length} cliente{visibleCustomers.length === 1 ? "" : "s"}</span></div><div className="table-scroll"><table><thead><tr><th>Empresa</th><th>CNPJ</th><th>Responsável</th><th>Contato</th><th>Operações</th><th>Status</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{visibleCustomers.length === 0 ? <tr><td className="empty-cell" colSpan={7}>Nenhum cliente encontrado.</td></tr> : visibleCustomers.map((customer) => <tr key={customer.id}><td><strong>{customer.tradeName || customer.legalName}</strong><small>{customer.legalName}</small></td><td>{customer.taxId}</td><td>{customer.contactName}</td><td><strong>{customer.email}</strong><small>{customer.phone}</small></td><td>{operationCount(customer)}</td><td><span className={`status status--${customer.status === "active" ? "success" : "neutral"}`}>{customer.status === "active" ? "Ativo" : "Inativo"}</span></td><td><button className="table-action" onClick={() => onEdit(customer)} aria-label={`Editar ${customer.tradeName || customer.legalName}`}><Pencil size={16} /></button></td></tr>)}</tbody></table></div></section></section>;
}
function Placeholder({ view, onNavigate }: { view: View; onNavigate: () => void }) { const title = navigation.find((item) => item.id === view)?.label ?? "Módulo"; return <section className="page"><div className="placeholder panel"><span><Archive size={28} /></span><p className="eyebrow">PRÓXIMA FRENTE</p><h1>{title}</h1><p>Este módulo já está reservado na arquitetura. A primeira entrega concentra a operação de importação ponta a ponta.</p><button className="button button--secondary" onClick={onNavigate}>Abrir operações</button></div></section>; }
